import sys

def digits(p):
    return len(p) > 0 and all('0' <= ch <= '9' for ch in p)

def ids_ok(part, numeric_no_zero):
    for ident in part.split('.'):
        if not ident:
            return False
        for ch in ident:
            if not (ch.isascii() and (ch.isalnum() or ch == '-')):
                return False
        if numeric_no_zero and digits(ident) and len(ident) > 1 and ident[0] == '0':
            return False
    return True

def valid(s):
    build = None
    if '+' in s:
        s, build = s.split('+', 1)
    pre = None
    if '-' in s:
        s, pre = s.split('-', 1)
    parts = s.split('.')
    if len(parts) != 3:
        return False
    for p in parts:
        if not digits(p) or (len(p) > 1 and p[0] == '0'):
            return False
    if pre is not None and not ids_ok(pre, True):
        return False
    if build is not None and not ids_ok(build, False):
        return False
    return True

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    print('\n'.join('valid' if valid(data[1 + i]) else 'invalid' for i in range(q)))

main()

